#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Sports Hub setup, from "nothing on GitHub" to the first Refresh.
# Run from the project folder:  bash scripts/setup-wizard.sh
# Safe to re-run: every stage checks what's already done and skips it.
# Secrets are typed into hidden prompts and passed straight to GitHub; this
# wizard never writes them to a file (so no .env is used).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7
REPO_NAME="sports-hub"
ENV_FILE=""   # nothing is saved locally, so the prompts never offer stored defaults
cd "$(dirname "$0")/.."

if ! command -v gh >/dev/null 2>&1; then
  printf '\n  This wizard needs the GitHub command-line tool (gh).\n'
  printf '  Install it with:  brew install gh   then run the wizard again.\n\n'
  exit 1
fi

banner "Sports Hub: put it on GitHub"

if [[ -n "$(git status --porcelain)" ]]; then
  warn "This project has changes that aren't saved in git yet:"
  git status --short | head -10
  say "Ask Claude to commit them (or commit them yourself), then run the wizard again."
  exit 1
fi

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to GitHub"
if gh auth status >/dev/null 2>&1; then
  say "You're already signed in to GitHub as $(gh api user --jq .login). Nothing to do here."
else
  say "The 'gh' tool needs to sign in to your GitHub account once."
  step "Choose GitHub.com, then HTTPS, then 'Login with a web browser'."
  step "It shows a one-time code: copy it, press Enter, and paste it in the page that opens."
  gh auth login --hostname github.com --git-protocol https --web
fi
GH_LOGIN=$(gh api user --jq .login)
GH_ID=$(gh api user --jq .id)
pause "Press Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Privacy check before going public"
say "The repo will be public, so anyone could read it. What's in it:"
step "the code, the Season file and watch guide (sport dates, streaming services)"
step "the design notes, which mention you and Jason by first name and Memphis"
step "no passwords or email addresses (those go in GitHub secrets in stage 6)"
NOREPLY="${GH_ID}+${GH_LOGIN}@users.noreply.github.com"
say ""
if [[ "$(git config user.email || true)" == "$NOREPLY" ]]; then
  note "Commits already use your private GitHub 'noreply' address."
else
  say "Each commit records an author email. Right now it's your Mac's name. GitHub"
  say "gives you a private 'noreply' address to use instead:"
  note "  $NOREPLY"
  if confirm "Use it for this project's commits?"; then
    git config user.email "$NOREPLY"
    git config user.name "$GH_LOGIN"
    printf '  %s✓ set%s commit author for this project\n' "$GREEN" "$RESET"
  fi
fi
if gh repo view "$GH_LOGIN/$REPO_NAME" >/dev/null 2>&1; then
  note "Already published, so the history is left as it is."
elif git show-ref --verify --quiet refs/heads/pre-publish-history; then
  note "The history was already started fresh (backup kept in 'pre-publish-history')."
else
  say ""
  say "The project's earlier commits still carry your Mac's name, plus some"
  say "old test data with event organisers' contact details (since removed)."
  say "Recommended: publish one fresh commit. The full history is kept on this"
  say "Mac only, in a branch called 'pre-publish-history'."
  if confirm "Start the public history fresh (recommended)?"; then
    git branch -f pre-publish-history HEAD
    tree=$(git write-tree)
    fresh=$(git commit-tree "$tree" -m "Sports Hub: Python rebuild (Milestones 1-4)")
    git reset --soft "$fresh"
    printf '  %s✓ done%s one fresh commit; old history saved in pre-publish-history (local only)\n' "$GREEN" "$RESET"
  else
    warn "Keeping the full history; it will be published as it is."
  fi
fi
pause "Press Enter to continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the public repo and upload the project"
if gh repo view "$GH_LOGIN/$REPO_NAME" >/dev/null 2>&1; then
  say "github.com/$GH_LOGIN/$REPO_NAME already exists."
  git remote get-url origin >/dev/null 2>&1 || git remote add origin "https://github.com/$GH_LOGIN/$REPO_NAME.git"
  if confirm "Upload any new commits to it now?"; then git push -u origin HEAD:main; fi
else
  say "This creates github.com/$GH_LOGIN/$REPO_NAME (public) and uploads the project."
  if confirm "Create the repo and upload?"; then
    git branch -M main
    # An 'origin' left from an earlier attempt points at a repo that doesn't exist.
    git remote get-url origin >/dev/null 2>&1 && git remote remove origin
    gh repo create "$REPO_NAME" --public --source=. --remote=origin --push \
      --description "A shared schedule of 19 sports, refreshed twice a week."
    if gh repo view "$GH_LOGIN/$REPO_NAME" >/dev/null 2>&1; then
      printf '  %s✓ created%s github.com/%s/%s\n' "$GREEN" "$RESET" "$GH_LOGIN" "$REPO_NAME"
    else
      warn "GitHub doesn't show the repo yet. Run the wizard again in a minute."
      finish; exit 1
    fi
  else
    SKIPPED+=("create the repo: gh repo create $REPO_NAME --public --source=. --remote=origin --push")
    finish; exit 0
  fi
fi
pause "Press Enter to continue"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Turn on GitHub Pages"
if [[ "$(gh api "repos/$GH_LOGIN/$REPO_NAME/pages" --jq .build_type 2>/dev/null || true)" == "workflow" ]]; then
  say "Pages is already on and published by the Refresh workflow."
else
  say "Pages is what puts the Hub online. It's published by the Refresh workflow,"
  say "not from a branch, so only the Hub itself goes on the web."
  if confirm "Turn on Pages for $REPO_NAME?"; then
    gh api -X POST "repos/$GH_LOGIN/$REPO_NAME/pages" -f build_type=workflow >/dev/null 2>&1 \
      || gh api -X PUT "repos/$GH_LOGIN/$REPO_NAME/pages" -f build_type=workflow >/dev/null 2>&1 || true
    if [[ "$(gh api "repos/$GH_LOGIN/$REPO_NAME/pages" --jq .build_type 2>/dev/null || true)" == "workflow" ]]; then
      printf '  %s✓ on%s Pages, published by GitHub Actions\n' "$GREEN" "$RESET"
    else
      warn "Pages didn't turn on. Do it by hand: repo Settings → Pages → Source: GitHub Actions."
      SKIPPED+=("turn on Pages: repo Settings → Pages → Source: GitHub Actions")
    fi
  else
    SKIPPED+=("turn on Pages: repo Settings → Pages → Source: GitHub Actions")
  fi
fi
pause "Press Enter to continue"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Make a Gmail app password"
existing=$(gh secret list --repo "$GH_LOGIN/$REPO_NAME" --json name --jq '.[].name' 2>/dev/null || true)
if grep -qx SPORTS_HUB_MAIL_APP_PASSWORD <<<"$existing" && ! confirm "An app password is already saved in GitHub. Make a new one?"; then
  note "Keeping the saved app password."
else
say "The Hub emails you if a Refresh has problems. It sends from your Gmail using"
say "an 'app password': a separate 16-letter password just for the Hub, which you"
say "can delete at any time without touching your real password."
say ""
say "App passwords need Google's 2-Step Verification turned on."
open_url "https://myaccount.google.com/signinoptions/twosv"
step "If it says 2-Step Verification is off, follow Google's steps to turn it on."
pause "Press Enter once 2-Step Verification is on"
open_url "https://myaccount.google.com/apppasswords"
step "Sign in if asked. Under 'App name' type: Sports Hub. Click Create."
step "Google shows a 16-letter password. Keep that window open for the next stage."
note "(If the page says app passwords aren't available, 2-Step Verification isn't on yet.)"
pause "Press Enter once you can see the 16-letter password"
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Add the secrets to GitHub"
say "These go into GitHub's encrypted secrets. They're never shown again, never"
say "written to a file and never put in the code."
existing=$(gh secret list --repo "$GH_LOGIN/$REPO_NAME" --json name --jq '.[].name' 2>/dev/null || true)
add_secret() {  # add_secret NAME "Prompt" hidden|visible
  local name="$1" prompt="$2" kind="$3" value=""
  if grep -qx "$name" <<<"$existing"; then
    confirm "$name is already set. Replace it?" || { note "kept $name"; return; }
  else
    confirm "Save $name to GitHub?" || { note "skipped $name"; SKIPPED+=("secret $name"); return; }
  fi
  if [[ "$kind" == hidden ]]; then ask_secret value "$prompt"; else ask value "$prompt"; fi
  [[ -n "$value" ]] || { warn "$name left empty; skipped"; SKIPPED+=("secret $name"); return; }
  local GH_REPO="$GH_LOGIN/$REPO_NAME"; export GH_REPO
  set_secret "$name" "$value"
  value=""
}
add_secret SPORTS_HUB_MAIL_USER "Your Gmail address (the account that made the app password):" visible
add_secret SPORTS_HUB_MAIL_APP_PASSWORD "Paste the 16-letter app password (hidden as you type):" hidden
add_secret SPORTS_HUB_ALERT_TO "Where should problem alerts go? (usually the same Gmail):" visible
note "You can close the Google window now; the app password won't be shown again."
pause "Press Enter to continue"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Start the first Refresh"
say "From now on GitHub runs the Refresh every Monday and Thursday at 11:00 UTC."
say "You can start one now so the Hub goes online today (takes about 2 minutes)."
if confirm "Start a Refresh now?"; then
  started=""
  for attempt in 1 2 3 4 5 6; do
    if gh workflow run refresh.yml --repo "$GH_LOGIN/$REPO_NAME" --ref main >/dev/null 2>&1; then started=yes; break; fi
    note "GitHub is still setting up the workflow; trying again in 10 seconds ($attempt/6)…"
    sleep 10
  done
  if [[ -n "$started" ]]; then
    printf '  %s✓ started%s\n' "$GREEN" "$RESET"
    run_id=""
    for attempt in 1 2 3 4 5 6; do
      sleep 5
      run_id=$(gh run list --repo "$GH_LOGIN/$REPO_NAME" --workflow refresh.yml --limit 1 --json databaseId --jq '.[0].databaseId // empty' 2>/dev/null || true)
      [[ -n "$run_id" ]] && break
    done
    if [[ -n "$run_id" ]] && confirm "Watch it run here until it finishes?"; then
      gh run watch "$run_id" --repo "$GH_LOGIN/$REPO_NAME" --exit-status \
        || warn "The run didn't finish cleanly. You'll get an email, and the log is linked below."
    fi
  else
    warn "Couldn't start the Refresh yet. Start it from the Actions page below: Refresh → Run workflow."
    SKIPPED+=("start the first Refresh: Actions → Refresh → Run workflow")
  fi
fi
say ""
say "Your Hub:          https://$GH_LOGIN.github.io/$REPO_NAME/"
say "Runs and logs:     https://github.com/$GH_LOGIN/$REPO_NAME/actions"
note "(The Hub link works once the first Refresh has finished.)"

finish
